  active: number;
}

/** A period's line of the summary: its due-total, and its change from the period before it by
 *  start date (empty for the earliest). */
export interface PeriodSummary {
  name: string;
  dueTotal: string;
  change: string;
}

/** A status's line of the summary: how many claims have it. */
export interface StatusSummary {
  status: string;
  count: number;
}

/** A void reason's line of the summary: how many void claims were voided with it. */
export interface VoidReasonSummary {
  reason: string;
  count: number;
}

// The sheet summed up: per grade, per period, per claim status and per void reason, with the figures the list shows.
@Component({
  selector: 'app-summary-panel',
  imports: [FigurePipe],
  template: `
    <section aria-labelledby="summary-heading" data-testid="summary">
      <h2 id="summary-heading">Summary</h2>
      <table>
        <caption>By grade</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">People</th><th scope="col">Due</th><th scope="col">Active</th></tr>
        </thead>
        <tbody>
          @for (g of grades(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ g.dueTotal | figure }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-active'">{{ g.active }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By period</caption>
        <thead>
          <tr><th scope="col">Period</th><th scope="col">Due</th><th scope="col">Change</th></tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'summary-period-' + p.name + '-due-total'">{{ p.dueTotal | figure }}</td>
              <td [attr.data-testid]="'summary-period-' + p.name + '-change'">{{ p.change | figure }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By status</caption>
        <thead>
          <tr><th scope="col">Status</th><th scope="col">Claims</th></tr>
        </thead>
        <tbody>
          @for (s of statuses(); track s.status) {
            <tr>
              <th scope="row">{{ s.status }}</th>
              <td [attr.data-testid]="'summary-status-' + s.status + '-count'">{{ s.count }}</td>
            </tr>
          }
        </tbody>
      </table>
      @if (voidReasons().length > 0) {
        <table>
          <caption>By void reason</caption>
          <thead>
            <tr><th scope="col">Reason</th><th scope="col">Void claims</th></tr>
          </thead>
          <tbody>
            @for (v of voidReasons(); track v.reason) {
              <tr>
                <th scope="row">{{ v.reason }}</th>
                <td [attr.data-testid]="'summary-void-' + v.reason + '-count'">{{ v.count }}</td>
              </tr>
            }
          </tbody>
        </table>
      }
    </section>
  `,
})
export class SummaryPanel {
  readonly grades = input.required<GradeSummary[]>();
  readonly periods = input.required<PeriodSummary[]>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly voidReasons = input.required<VoidReasonSummary[]>();
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, input, output, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { AMOUNT, CLAIM_AMOUNT, Claim, ClaimAction, Claims, claimDue, deferred, overdue } from '../../core/claims';
import { ClaimTemplates } from '../../core/claim-templates';
import { GradeFrom, Person, gradeOn } from '../../core/people';
import { Period, periodOf } from '../../core/periods';
import { Rate } from '../../core/rates';
import { Session } from '../../core/session';
import { VoidReasons } from '../../core/void-reasons';
import { DatedValue, Graces, RoundingMode, graceOn } from '../../core/settings';
import { FigurePipe } from '../../core/figure';
import { AuditLog } from '../../core/audit-log';

/** Why the server refused an action: the claim's status does not allow it. */
const REFUSALS: Record<ClaimAction, string> = {
  open: 'Only a draft claim can be opened, and only while its person is under its period\'s cap of open claims.',
  settle: 'Only an open claim that is not deferred can be settled.',
  resettle: 'Only a settled claim can be re-settled.',
  void: 'Only a draft, review, open or pending claim can be voided, or a settled one within 7 days of its settlement.',
  approve: 'Only a pending claim can be approved.',
  reject: 'Only a pending claim can be rejected.',
  delete: 'Only a draft claim can be deleted.',
  restore: 'Only a deleted claim can be restored, on the day it was deleted.',
  review: 'Only a claim in review can be reviewed.',
};

/** The message when an edit of a claim that is not a draft is refused. */
const NOT_DRAFT = 'Only a draft claim can be edited; void an open claim and add a new one.';

/** The message when another user has the claim's editor open. */
const EDIT_LOCKED = 'Another user is editing this claim; try again once they save or cancel.';

/** The message for a refused opening of a claim's editor. */
function editorRefusal(e: unknown, c: Claim): string {
  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
  if (e instanceof HttpErrorResponse && e.status === 403) return 'Your role may not edit a claim.';
  if (e instanceof HttpErrorResponse && e.status === 409) return c.status === 'DRAFT' ? EDIT_LOCKED : NOT_DRAFT;
  return 'The claim\'s editor could not be opened.';
}

/** The message when the server refused a change to a claim dated inside a closed period. */
const CLOSED = 'The claim\'s period is closed.';
const RETIRED = 'A claim cannot be dated after the person\'s retirement.';
const CORRECTS = 'A negative amount must name the number of a settled claim of this person.';
const REF_USED = 'That reference is already used on this sheet.';
const REF_LONG = 'Enter a reference of at most 120 characters.';

/** The message for a refused action on a claim. */
function refusal(e: unknown, action: ClaimAction): string {
  if (e instanceof HttpErrorResponse && e.status === 423) return CLOSED;
  if (e instanceof HttpErrorResponse && e.status === 409) return REFUSALS[action];
  if (e instanceof HttpErrorResponse && e.status === 428) return NEEDS_PROOF;
  if (e instanceof HttpErrorResponse && e.status === 422 && action === 'open') {
    return 'A claim whose due is above the note threshold needs a note before it is opened.';
  }
  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'settle') {
    return 'The user who opened or last edited a claim cannot settle it.';
  }
  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'void') {
    return 'Your role may not void this claim; only a steward may void a settled claim.';
  }
  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'review') {
    return 'Only a steward can review a claim.';
  }
  if (e instanceof HttpErrorResponse && e.status === 403 && action === 'resettle') {
    return 'Only a steward can re-settle a claim.';
  }
  if (e instanceof HttpErrorResponse && e.status === 403 && (action === 'approve' || action === 'reject')) {
    return action === 'approve' ? 'Only a steward who did not open or last edit the claim can approve it.'
      : 'Only a steward can reject a claim.';
  }
  if (e instanceof HttpErrorResponse && e.status === 400 && action === 'reject') {
    return 'Enter a reason for rejecting the claim.';
  }
  if (e instanceof HttpErrorResponse && e.status === 400 && action === 'void') {
    return 'Choose a void reason from the sheet\'s list.';
  }
  return 'The claim could not be changed.';
}
